const updateParentTimeSpentIncremental = (
  parentId: string,
  oldTimeSpentOnDay: TimeSpentOnDay | undefined,
  newTimeSpentOnDay: TimeSpentOnDay,
  state: TaskState,
): TaskState => {
  const parent = state.entities[parentId];
