    const oldVal = oldTimeSpentOnDay?.[day] || 0;
    const newVal = newTimeSpentOnDay[day] || 0;
    const delta = newVal - oldVal;

    if (delta !== 0) {
      totalDelta += delta;
      const currentParentVal = parentTimeSpentOnDay[day] || 0;
      const newParentVal = currentParentVal + delta;

